-- myUNO — minimal demo data so the deployed app has properties to show.
--
-- Paste into the Supabase SQL editor and run once. Idempotent: every insert
-- skips rows that already exist, so a second run changes nothing.
--
-- What this is NOT: the full staging seed (`npm run db:seed`), which also loads
-- 1237 content keys, 2869 translations, 42 villas, and a walkthrough of
-- bookings, statements and reviews. That one needs a terminal. This is the
-- subset that makes search and booking work when all you have is a browser.
--
-- Content keys are deliberately omitted: the app falls back to English when a
-- key is missing, which is why the deployed page already reads correctly.

BEGIN;

-- Configuration registry (76 parameters). Pricing and booking read these;
-- a missing row returns undefined, which breaks money math quietly.

-- The project -------------------------------------------------------------

-- Ten villas, live and permitted-use confirmed ------------------------------

COMMIT;

SELECT (SELECT count(*) FROM unit WHERE status='live')     AS live_villas,
       (SELECT count(*) FROM project WHERE status='live')  AS live_projects,
       (SELECT count(*) FROM config_parameter)             AS config_parameters;
